@Override
public List<List<DetectedLanguage>> detect(List<String> texts) {
  try {
    ImmutableList.Builder<List<DetectedLanguage>> detections = ImmutableList.builder();
    for (String text : texts) {
      DetectLanguageRequest request = new DetectLanguageRequest();
      request.setContent(text);
      List<DetectedLanguage> result =
          translate
              .projects()
              .detectLanguage("-", request)
              .setKey(options.getApiKey())
              .execute()
              .getLanguages();
      detections.add(result != null ? result : ImmutableList.<DetectedLanguage>of());
    }
    return detections.build();
  } catch (IOException ex) {
    throw translate(ex);
  }
}

