@Override
public List<LanguagesResource> listSupportedLanguages(Map<Option, ?> optionMap) {
  try {
    List<LanguagesResource> languages =
        translate
            .languages()
            .list()
            .setKey(options.getApiKey())
            .setTarget(
                firstNonNull(
                    Option.TARGET_LANGUAGE.getString(optionMap), options.getTargetLanguage()))
            .execute()
            .getLanguages();
    return languages != null ? languages : ImmutableList.<LanguagesResource>of();
  } catch (IOException ex) {
    throw translate(ex);
  }
}

arguments.new_string:
@Override
public List<SupportedLanguage> listSupportedLanguages(Map<Option, ?> optionMap) {
  try {
    String displayLanguageCode =
        firstNonNull(
            Option.TARGET_LANGUAGE.getString(optionMap), options.getTargetLanguage());
    List<SupportedLanguage> languages =
        translate
            .projects()
            .getSupportedLanguages("-")
            .setKey(options.getApiKey())
            .setDisplayLanguageCode(displayLanguageCode)
            .execute()
            .getLanguages();
    return languages != null ? languages : ImmutableList.<SupportedLanguage>of();
  } catch (IOException ex) {
    throw translate(ex);
  }
