  @Override
  public List<TranslationsResource> translate(List<String> texts, Map<Option, ?> optionMap) {
    try {
      String targetLanguage =
          firstNonNull(Option.TARGET_LANGUAGE.getString(optionMap), options.getTargetLanguage());
      final String sourceLanguage = Option.SOURCE_LANGUAGE.getString(optionMap);
      List<TranslationsResource> translations =
          translate
              .translations()
              .list(texts, targetLanguage)
              .setSource(sourceLanguage)
              .setKey(options.getApiKey())
              .setModel(Option.MODEL.getString(optionMap))
              .setFormat(Option.FORMAT.getString(optionMap))
              .execute()
              .getTranslations();
      return Lists.transform(
          translations != null ? translations : ImmutableList.<TranslationsResource>of(),
          new Function<TranslationsResource, TranslationsResource>() {
            @Override
            public TranslationsResource apply(TranslationsResource translationsResource) {
              if (translationsResource.getDetectedSourceLanguage() == null) {
                translationsResource.setDetectedSourceLanguage(sourceLanguage);
              }
              return translationsResource;
            }
          });
    } catch (IOException ex) {
      throw translate(ex);
    }
  }
}

arguments.new_string:
  @Override
  public List<Translation> translate(List<String> texts, Map<Option, ?> optionMap) {
    try {
      String targetLanguage =
          firstNonNull(Option.TARGET_LANGUAGE.getString(optionMap), options.getTargetLanguage());
      final String sourceLanguage = Option.SOURCE_LANGUAGE.getString(optionMap);
      String model = Option.MODEL.getString(optionMap);
      String format = Option.FORMAT.getString(optionMap);

      TranslateTextRequest request = new TranslateTextRequest();
      request.setContents(texts);
      request.setTargetLanguageCode(targetLanguage);
      request.setSourceLanguageCode(sourceLanguage);
      request.setModel(model);
      if ("html".equalsIgnoreCase(format)) {
        request.setMimeType("text/html");
      }

      List<Translation> translations =
          translate
              .projects()
              .translateText("-", request)
              .setKey(options.getApiKey())
              .execute()
              .getTranslations();

      return Lists.transform(
          translations != null ? translations : ImmutableList.<Translation>of(),
          new Function<Translation, Translation>() {
            @Override
            public Translation apply(Translation translation) {
              if (translation.getDetectedLanguageCode() == null) {
                translation.setDetectedLanguageCode(sourceLanguage);
              }
              return translation;
            }
          });
    } catch (IOException ex) {
      throw translate(ex);
    }
  }
}

